schemaSql:
CREATE TABLE Person (
  personId INTEGER PRIMARY KEY,
  lastName TEXT,
  firstName TEXT
);

CREATE TABLE Address (
  addressId INTEGER PRIMARY KEY,
  personId INTEGER,
  city TEXT,
  state TEXT
);

solutionSql:
SELECT p.firstName, p.lastName, a.city, a.state
FROM Person p
LEFT JOIN Address a ON p.personId = a.personId;
